    public static void main(String[] args) {
        LampReceipt lampReceipt = LampReceiptKt.receipt(new Lamp("desk lamp", 1, null), "Ana");
        VanReceipt vanReceipt = VanReceiptKt.receipt(new Van("MV-1", lampReceipt), "Ben");

        System.out.println(BoxInventoryCardKt.inventoryCard(new Box("plates", "kitchen", 4200, true)));
        System.out.println(LampReceiptInventoryCardKt.inventoryCard(lampReceipt));
        System.out.println(VanReceiptInventoryCardKt.inventoryCard(vanReceipt));
    }
}

java.src:
// Closest Java equivalent: a javac annotation processor
private final Set<String> waiting = new LinkedHashSet<>();
private int round = 0;

@Override
public boolean process(Set<? extends TypeElement> annotations, RoundEnvironment roundEnv) {
    round++;
    Elements elements = processingEnv.getElementUtils();
    List<TypeElement> candidates = new ArrayList<>();
    for (Element e : roundEnv.getElementsAnnotatedWith(Moving.class)) candidates.add((TypeElement) e);
    for (String name : waiting) candidates.add(elements.getTypeElement(name));   // no deferral: look up again
    waiting.clear();
    for (TypeElement type : candidates) {
        if (hasErrorTypes(type)) waiting.add(type.getQualifiedName().toString());
        else writeReceipt(type);
    }
    if (roundEnv.processingOver()) {                 // javac's extra, final round
        for (String name : waiting) {
            processingEnv.getMessager().printMessage(Diagnostic.Kind.ERROR,
                    name + "Receipt was never written", elements.getTypeElement(name));
        }
    }
    return false;
}

kotlin.src:
private var round = 0
private var waiting: List<KSAnnotated> = emptyList()

override fun process(resolver: Resolver): List<KSAnnotated> {
    round++
    val symbols = resolver.getSymbolsWithAnnotation(Moving::class.qualifiedName!!).toList()
    val (ready, later) = symbols.partition { it.validate(apiFeatures = apiFeatures) }
    for (symbol in ready) {
        if (check(symbol)) receiptFile(symbol as KSClassDeclaration).writeTo(codeGenerator, aggregating = false)
    }
    waiting = later
    return later                                      // KSP hands these back next round
}

override fun finish() {                               // once, after the last round
    for (symbol in waiting) {
        logger.error("${receiptName(symbol as KSClassDeclaration).simpleName} was never written", symbol)
    }
}

