private var round = 0
private var waiting: List<KSAnnotated> = emptyList()

override fun process(resolver: Resolver): List<KSAnnotated> {
    round++
    val (ready, later) = resolver.getSymbolsWithAnnotation("workbench.ksp.annotations.Moving").toList()
        .partition { it.validate(apiFeatures = apiFeatures) }
    ready.forEach(::write)
    waiting = later
    return later                 // KSP offers these again next round
}

override fun finish() {
    for (symbol in waiting) logger.error("still set aside after $round rounds", symbol)
}

